const HOESRC={"hoe": "data:image/png;base64,", "snow": "data:image/png;base64,"};
/* ═════════ 밭: 스듀 경작지 그림(칸 이어짐) · 젖은 땅 진갈색 · 비 오면 자동으로 젖음 · 물주기/심기 3칸씩 ═════════ */
const HOE={};for(const [k,src] of Object.entries(HOESRC)){const im=new Image();HOE[k]={im,ok:false};im.onload=()=>HOE[k].ok=true;im.src=src;}
/* 이웃(위·아래·왼·오) → 4×4 칸 위치 */
function hoeIdx(u,d,l,r){if(!u&&!d&&!l&&!r)return [0,0];if(!l&&!r){if(d&&!u)return [0,1];if(u&&d)return [0,2];return [0,3];}if(!u&&!d){if(r&&!l)return [1,3];if(l&&r)return [2,3];return [3,3];}
  const cx=!l?1:!r?3:2,cy=!u?0:!d?2:1;return [cx,cy];}
const farmRain=()=>S.area==='castle'&&(S.weather==='rain'||S.weather==='blizzard')&&FSEA()!=='겨울';
function farmWet(k,p){const f=F();return (p&&!p.dead&&p.wd===S.day)||(f.wet&&f.wet[k]===S.day)||(farmRain()&&k.startsWith('castle:'));}
function hoeDraw(x,y,sx,sy,p,ss){const k=PK(S.area,x,y),ice=S.area==='castle'&&ss==='겨울',wet=!ice&&farmWet(k,p);const H=ice?HOE.snow:HOE.hoe;
  if(!H||!H.ok){ctx.drawImage(soilCv(wet?'wet':ice?'ice':'dry'),sx,sy);return;}
  const n=(a,b)=>isPlot(S.area,x+a,y+b),[ix,iy]=hoeIdx(n(0,-1),n(0,1),n(-1,0),n(1,0));
  ctx.drawImage(H.im,ix*16,iy*16,16,16,sx,sy,16,16);if(wet)ctx.drawImage(H.im,64+ix*16,iy*16,16,16,sx,sy,16,16);}
/* 심을 때 땅이 젖어 있으면(물 준 칸·비) 바로 물 준 것으로 */
{const _pl=plant;plant=function(k,c){_pl(k,c);const f=F(),p=f.pl[k];if(p&&farmWet(k,null))p.wd=S.day;};}
/* 물뿌리개: 기본은 바라보는 방향으로 3칸, 좋은 물뿌리개는 3×3. 빈 밭도 젖음 */
water=function(x,y){const f=F();if(!S.inv.can&&!S.inv.can2){startDialog(null,[R_('물뿌리개가 없다.')]);return;}if(S.hp<1){toast('너무 지쳤다');return;}
  if(farmRain()){toast('비가 와서 밭이 저절로 젖었어요');return;}
  const [dx,dy]=DIRV[P.dir],cells=[];if(S.inv.can2){for(let j=-1;j<=1;j++)for(let i=-1;i<=1;i++)cells.push([x+i,y+j]);}else for(let i=0;i<3;i++)cells.push([x+dx*i,y+dy*i]);
  f.wet=f.wet||{};let n=0;
  for(const [cx_,cy_] of cells){if(!isPlot(S.area,cx_,cy_))continue;const k=PK(S.area,cx_,cy_),p=f.pl[k];if(farmWet(k,p))continue;
    if(p&&!p.dead)p.wd=S.day;f.wet[k]=S.day;n++;FFX.push({k:'water',x:cx_*T+8,y:cy_*T+10,t:performance.now()+(Math.abs(cx_-x)+Math.abs(cy_-y))*70});}
  for(const k in f.wet)if(f.wet[k]!==S.day)delete f.wet[k];
  if(!n){toast('이미 촉촉해요');return;}S.hp-=S.inv.can2?.8:.6;S.min+=2;P.waterT=performance.now();hud();save();
  if(!S.seen.farmW){S.seen.farmW=1;toast('물을 준 날 밤에 한 칸씩 자라요 · 비 오는 날은 저절로 젖어요');}};
/* 씨앗: 바라보는 방향으로 빈 칸 3칸까지 한 번에 */
{const _fa=farmAct;farmAct=function(tx,ty,ob){const f=S.farm;const pt=f&&f.intro&&farmTile(tx,ty);
  if(pt){const k=PK(S.area,pt[0],pt[1]);if(!f.pl[k]&&f.sel&&S.inv['s_'+f.sel]&&inSeason(f.sel,S.area)&&!(S.area==='castle'&&FSEA()==='겨울')){const [dx,dy]=DIRV[P.dir];let n=0;
      for(let i=0;i<3;i++){const x=pt[0]+dx*i,y=pt[1]+dy*i,kk=PK(S.area,x,y);if(!isPlot(S.area,x,y)||f.pl[kk]||!S.inv['s_'+f.sel]||S.hp<2)break;plant(kk,f.sel);n++;}
      if(n>1)toast(`${CROPS[f.pl[k].c].n} ${n}칸 심음 <i>남은 씨앗 ${S.inv['s_'+f.pl[k].c]||0}</i>`);return true;}}
  return _fa(tx,ty,ob);};}
/* 라벨: 비 오는 날엔 물 주기 대신 살펴보기 */
{const _fl=farmLabel;farmLabel=function(tx,ty,ob){const l=_fl(tx,ty,ob);if(l==='물 주기'&&farmRain())return '살펴보기';if(l==='물 주기'&&S.inv&&!S.inv.can2)return '물 주기 (3칸)';if(l==='물 주기')return '물 주기 (3×3)';if(l&&/심기$/.test(l)&&S.farm&&S.farm.sel)return l+' (3칸)';return l;};}
/* 메뉴 첫 칸에 «꾸미기» */
const PX_DECO=['......KK..','.....KYYK.','....KYYK..','...KNNK...','..KNNK....','.KRRK.....','KRRRK.....','KRRK......','.KK.......','..........'];
{const _tpD=togglePanel;togglePanel=function(kind,arg,keep){_tpD(kind,arg,keep);const p=$('#panel');if(!p||p.hidden||kind!=='menu')return;const tabs=p.querySelector('.tabs');if(!tabs||tabs.querySelector('[data-deco]'))return;
  const b=document.createElement('button');b.className='tab';b.dataset.deco='1';b.innerHTML=(typeof pxSvg==='function'?pxSvg(PX_DECO):'')+'<span>꾸미기</span>';b.onclick=e=>{e.stopPropagation();edEnter();};tabs.appendChild(b);};}

const RPSRC={"bin": "data:image/png;base64,", "coop": "data:image/png;base64,", "trough": "data:image/png;base64,", "egg": "data:image/png;base64,", "eggb": "data:image/png;base64,", "hay": "data:image/png;base64,"};

/* ═════════ 리텍 소품: 출하 상자 · 닭장 건물 · 물여물통 · 달걀 · 건초 / 마을 길가 코드 상자 제거 ═════════ */
const RP={};for(const [k,src] of Object.entries(RPSRC)){const im=new Image();RP[k]={im,ok:false};im.onload=()=>{RP[k].ok=true;if(k==='hay')setTimeout(()=>{for(const id of ['castle','stable']){const a=AREAS[id];if(!a)continue;if(a.outdoor&&typeof SEAS_CACHE!=='undefined')SEAS_CACHE[id]={};buildArea(a);if(a.outdoor&&typeof SEAS_CACHE!=='undefined'&&typeof SEAS!=='undefined')SEAS_CACHE[id][SEAS]={cv:a.cv,dyn:a.dyn,full:a.full};}if(S&&AREAS[S.area])A=AREAS[S.area];},50);RP[k].c=(()=>{const h=k==='coop'?112:im.height;const c=document.createElement('canvas');c.width=im.width;c.height=h;c.getContext('2d').drawImage(im,0,0,im.width,h,0,0,im.width,h);return c;})();};im.src=src;}
const rpc=k=>RP[k]&&RP[k].ok?RP[k].c:null;
/* 위치: 출하 상자 2×2(밭 왼쪽), 닭장 6칸(목장 위 울타리 줄), 여물통 2칸 */
BIN.x=42;BIN.y=23;COOP.x=56;COOP.y=49;TROUGH.x=52;TROUGH.y=50;
const COOPB={x:55,y:44,w:6,h:7};   /* 그림 96×128, 막힘 x55~60 · y44~50, 문 x56~57 */
{const a=AREAS.castle;if(a){for(let x=55;x<=60;x++)if(a.map[44][x]==='=')a.map[44][x]=a.floor&&a.floor[44][x]&&a.floor[44][x]!=='='?a.floor[44][x]:',';
  for(const o of a.objs){if(o.k==='horse'&&o.x===56&&o.y===51){o.x=51;o.y=53;}if(o.k==='hay'&&o.x===59&&o.y===46){o.x=58;o.y=52;o.rp='hay';}}
    const re=()=>{for(let k=0;k<a.MW*a.MH;k++){const o=a.otile&&a.otile[k];if(o&&(o.k==='horse'||o.k==='hay'))delete a.otile[k];}for(const o of a.objs)if(o.k==='horse'||o.k==='hay')for(let j=0;j<o.h;j++)for(let i=0;i<o.w;i++){const k=(o.y+j)*a.MW+o.x+i;a.blk[k]=1;a.otile[k]=o;}};
  for(const [x,y] of [[56,51],[57,51],[59,46],[60,46]]){a.blk[y*a.MW+x]=0;if(a.otile)delete a.otile[y*a.MW+x];}re();}}
/* 마을 길가의 코드 상자(X)·통(V) 없앰 */
{const a=AREAS.town;if(a)for(let y=0;y<a.MH;y++)for(let x=0;x<a.MW;x++){const c=a.map[y][x];if(c==='X'||c==='V'){const f=a.floor&&a.floor[y][x];a.map[y][x]=f&&!'XV'.includes(f)?f:((a.map[y][x-1]===':'||a.map[y][x+1]===':')?':':',');if(a.blk)a.blk[y*a.MW+x]=0;}}}
/* 막힘: 출하 상자 2×2, 닭장(닭이 있을 때) 6×7, 여물통 2칸 */
farmBlk=function(){const a=AREAS.castle,n=S.farm?S.farm.hens:0;if(FBLK===n+1)return;FBLK=n+1;
  for(const [x,y] of [[43,24],[47,45],[48,45],[47,46],[48,46],[49,46]])a.blk[y*a.MW+x]=0;
  for(let j=0;j<2;j++)for(let i=0;i<2;i++)a.blk[(BIN.y+j)*a.MW+BIN.x+i]=1;
  for(let j=0;j<COOPB.h;j++)for(let i=0;i<COOPB.w;i++)a.blk[(COOPB.y+j)*a.MW+COOPB.x+i]=n?1:0;
  for(let i=0;i<2;i++)a.blk[TROUGH.y*a.MW+TROUGH.x+i]=n?1:0;};
/* 상호작용: 출하 상자·여물통 칸 넓힘, 닭장은 문(56~57, 49~50) */
const inBin=(x,y)=>x>=BIN.x&&x<BIN.x+2&&y>=BIN.y&&y<BIN.y+2,inTr=(x,y)=>y===TROUGH.y&&(x===TROUGH.x||x===TROUGH.x+1);
{const _l=farmLabel;farmLabel=function(tx,ty,ob){if(S.area==='castle'){if(inBin(tx,ty))return _l(BIN.x,BIN.y,ob);if(inTr(tx,ty))return _l(TROUGH.x,TROUGH.y,ob);}return _l(tx,ty,ob);};}
{const _a=farmAct;farmAct=function(tx,ty,ob){if(S.area==='castle'){if(inBin(tx,ty))return _a(BIN.x,BIN.y,ob);if(inTr(tx,ty))return _a(TROUGH.x,TROUGH.y,ob);}return _a(tx,ty,ob);};}
/* 그림 바꾸기: farmEnts가 넣는 위치 기준(binCv px=BIN.x*T-1, py=BIN.y*T-6 / coop px=COOP.x*T-1, py=COOP.y*T-12 / trough px=TROUGH.x*T, py=TROUGH.y*T+4) */
{const _fe=farmEnts;farmEnts=function(ents,cx,cy,t){const n0=ents.length;_fe(ents,cx,cy,t);
  for(let i=n0;i<ents.length;i++){const e=ents[i],o=e.obj;if(!o||!o.c)continue;
    if(o.c===BINCV&&rpc('bin')){o.c=rpc('bin');o.px=BIN.x*T;o.py=(BIN.y+2)*T-32;e.y=(BIN.y+2)*T-2;}
    else if(o.c===COOPCV&&rpc('coop')){o.c=rpc('coop');o.px=COOPB.x*T;o.py=(COOPB.y+COOPB.h)*T-112;e.y=(COOPB.y+COOPB.h)*T-2;}
    else if(o.py===TROUGH.y*T+4&&o.px===TROUGH.x*T&&rpc('trough')){const fed=S.farm&&S.farm.fed===S.day;const c=document.createElement('canvas');c.width=32;c.height=16;const g=c.getContext('2d');g.drawImage(rpc('trough'),0,0);if(fed&&rpc('hay')){g.drawImage(rpc('hay'),4,4,24,6,4,3,24,6);}o.c=c;o.px=TROUGH.x*T;o.py=TROUGH.y*T;e.y=TROUGH.y*T+14;}}};}
/* 달걀: 리텍 아이템 그림 */
{const _eg=eggCv;eggCv=function(big,br){const c=rpc(big?'eggb':'egg');return c||_eg(big,br);};}
{const _fg=farmGround;farmGround=function(cx,cy,t){const f=S.farm,eg=f&&f.eggs;if(eg&&rpc('egg')&&S.area==='castle'){f.eggs=null;_fg(cx,cy,t);f.eggs=eg;for(const [x,y,big,i] of eg){const sx=x*T+(i*5)%7-cx-3,sy=y*T+(i*3)%5-cy-6;ctx.drawImage(rpc(big?'eggb':'egg'),sx,sy);}}else _fg(cx,cy,t);};}
/* 닭: 새 닭장 앞마당에서 돌아다님 */
{const _ht=hensTick;hensTick=function(dt){_ht(dt);for(const h of HENS){if(h.mode==='walk'&&h.tx>=54.5*T){h.tx=(47+Math.random()*7)*T;}if(h.ty<(51*T)&&h.tx>=53*T)h.ty=51.5*T+Math.random()*T;}};}
